(function() {
  var BADGE_CLASS = 'cs-word-counter-badge';

  function countWords(text) {
    if (!text || typeof text !== 'string') return 0;
    var trimmed = text.trim();
    if (trimmed.length === 0) return 0;
    return trimmed.split(/\s+/).length;
  }

  function createBadge(count) {
    var badge = document.createElement('span');
    badge.className = BADGE_CLASS;
    badge.textContent = count + ' word' + (count !== 1 ? 's' : '');
    badge.style.cssText = 'display:inline-block;padding:2px 8px;font-size:11px;color:#667;background:#f0f1f3;border-radius:10px;margin-left:8px;font-weight:500;';
    return badge;
  }

  function removeBadges() {
    var badges = document.querySelectorAll('.' + BADGE_CLASS);
    for (var i = 0; i < badges.length; i++) {
      badges[i].parentNode.removeChild(badges[i]);
    }
  }

  function attachBadge(cardEl) {
    var existing = cardEl.querySelector('.' + BADGE_CLASS);
    if (existing) existing.parentNode.removeChild(existing);
    var bodyEl = cardEl.querySelector('.cs-card-body, .card-body, [data-card-body]');
    if (!bodyEl) return;
    var text = bodyEl.textContent || '';
    var count = countWords(text);
    var header = cardEl.querySelector('.cs-card-header, .card-header, [data-card-header]');
    var target = header || bodyEl;
    target.appendChild(createBadge(count));
  }

  CardSpoke_MODS.register({
    name: 'Word Counter',
    hooks: {
      onAppInit: function() {
        console.log('[Word Counter] Plugin initialized');
      },
      onCardRender: function(cardData) {
        if (cardData && cardData.element) {
          attachBadge(cardData.element);
        } else {
          var cards = document.querySelectorAll('.cs-card, [data-card]');
          for (var i = 0; i < cards.length; i++) {
            attachBadge(cards[i]);
          }
        }
      },
      onDisable: function() {
        removeBadges();
        console.log('[Word Counter] Plugin disabled, badges removed');
      }
    }
  });
})()
